    {
      "path": "packages/plugin/cordis.patch.yml",
      "content": "# opencode2dsh DSH plugin — bundle patch: insert the plugin row (deployment-global).\n#\n# Defaults need no edits: the plugin spawns the agent on a random loopback port,\n# generates/persists the local token, and registers itself into llm-pi-ai.\n# Override any option via the config object below (see src/config.ts).\n- insert:\n    - id: opencode2dsh\n      name: '@opencode2dsh/dsh-plugin'\n      config: {}\n"
